// รับข้อมูลจาก WF1/WF2 → สร้าง payload ให้ FastAPI
const d = $input.first().json;
return [{
  json: {
    device_id: d.device_id || 'TEST1-00001',
    title: d.title || d.problem || (d.symptom ? d.symptom.slice(0,100) : 'แจ้งซ่อมจาก LINE'),
    description: d.problem_detail || d.symptom || '',
    reporter_name: d.reporter_name || 'ผู้ใช้ LINE',
    reporter_phone: d.contact || '',
    priority: (d.urgency || 'normal').toLowerCase() === 'high' ? 'high' : (d.urgency || '').toLowerCase() === 'critical' ? 'critical' : 'normal',
    channel: 'line'
  }
}];
